  function iuGamesPreviewRefresh(){
    try{
      const card = iuGamesPreviewEnsureDom();
      if (!card) return;
      const elFresh = card.querySelector("[data-iu-games-preview-freshness]");
      const elT1 = card.querySelector("[data-iu-games-preview-title-1]");
      const elT2 = card.querySelector("[data-iu-games-preview-title-2]");
      const elImg = document.getElementById("iuGamesPreviewImage");
      if (!elT1 || !elT2 || !elFresh) return;

      const fixedThumb = "/assets/images/hry-default.jpg";
      const picked = iuGamesPreviewPickLatestTwoFromState();
      const latest = picked.latest;
      const second = picked.second;
      let latestTitle = latest && latest.title ? String(latest.title) : "";
      let secondTitle = second && second.title ? String(second.title) : "";
      if (!iuPreviewTrustsSectionPreviewItems(picked) && latest && !iuArticleMatchesMediaTopicKey(latest, "hry")) {
        latestTitle = "";
      }
      if (!iuPreviewTrustsSectionPreviewItems(picked) && second && !iuArticleMatchesMediaTopicKey(second, "hry")) {
        secondTitle = "";
      }
      const hasLatest = !!latestTitle;

      if (
        iuTallPreviewHoldStableWhenTransientEmpty(
          card,
          elT1,
          hasLatest,
          "data-iu-games-preview-has-latest",
          "Hry se načítají",
        )
      ) {
        return;
      }

      if (hasLatest) {
        card.setAttribute("data-iu-games-preview-has-latest", "1");
        card.setAttribute("data-iu-games-preview-latest-title", latestTitle);
        card.setAttribute("data-iu-games-preview-guard-topic", "hry");
      } else {
        card.setAttribute("data-iu-games-preview-has-latest", "0");
        card.removeAttribute("data-iu-games-preview-latest-title");
        card.removeAttribute("data-iu-games-preview-guard-topic");
      }
      if (secondTitle && !iuDesktopHomeGridOmitSecondaryHeadline()) {
        card.setAttribute("data-iu-games-preview-second-title", secondTitle);
      } else {
        card.removeAttribute("data-iu-games-preview-second-title");
      }

      if (!hasLatest) {
        elFresh.textContent = "";
        elFresh.setAttribute("data-iu-games-preview-has-freshness", "0");
        card.removeAttribute("data-iu-games-preview-latest-ms");
        card.removeAttribute("data-iu-games-preview-published-raw");
        elT1.textContent = "Hry se načítají";
        elT2.textContent = "";
        try { elT2.classList.add("iuNewsPreviewHeadline2--empty"); } catch (_) {}
        try {
          iuPreviewImgApplyThumb(elImg, fixedThumb);
        } catch (_) {}
        try { iuGamesPreviewRegressionAudit(); } catch (_) {}
        return;
      }

      elT1.textContent = latestTitle;
      if (iuDesktopHomeGridOmitSecondaryHeadline()) {
        elT2.textContent = "";
        try { elT2.classList.add("iuNewsPreviewHeadline2--empty"); } catch (_) {}
      } else if (secondTitle) {
        elT2.textContent = secondTitle;
        try { elT2.classList.remove("iuNewsPreviewHeadline2--empty"); } catch (_) {}
      } else {
        elT2.textContent = "";
        try { elT2.classList.add("iuNewsPreviewHeadline2--empty"); } catch (_) {}
      }

      const publishedRaw = iuNewsPreviewPublishedRaw(latest);
      const ms = picked.latestMs;
      const fresh = iuCsRelativeFreshnessFromMs(ms, Date.now());
      if (fresh) {
        elFresh.textContent = fresh;
        elFresh.setAttribute("data-iu-games-preview-has-freshness", "1");
        card.setAttribute("data-iu-games-preview-latest-ms", String(ms));
        if (publishedRaw) card.setAttribute("data-iu-games-preview-published-raw", publishedRaw);
        else card.removeAttribute("data-iu-games-preview-published-raw");
      } else {
        elFresh.textContent = "";
        elFresh.setAttribute("data-iu-games-preview-has-freshness", "0");
        card.removeAttribute("data-iu-games-preview-latest-ms");
        card.removeAttribute("data-iu-games-preview-published-raw");
      }

      try {
        iuPreviewImgApplyThumb(elImg, fixedThumb);
      } catch (_) {}
      try { iuGamesPreviewRegressionAudit(); } catch (_) {}
    }catch(_){}
  }

