  function iuCountArticlesInList(arr) {
    if (!Array.isArray(arr)) return 0;
    let n = 0;
    for (let i = 0; i < arr.length; i++) {
      const ct = String(arr[i] && arr[i].contentType ? arr[i].contentType : "article").toLowerCase();
      if (ct === "article") n++;
    }
    return n;
  }

